"""Render the Hinglish STT board after a measured scheduled/manual run."""
from __future__ import annotations
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
RESULTS=ROOT/'benchmarks/code_switching/results.json'; OUT=ROOT/'docs/code-switching'
def e(x): return html.escape(str(x))
def main():
    if not RESULTS.exists():
        print('no measured Hinglish results yet; leaving deployed page unchanged'); return
    p=json.loads(RESULTS.read_text()); rows=p['results']
    trs=''.join(f'<tr><td>{e(r["provider"])}</td><td>{e(r["model"])}</td><td>{r["script_balance"]:.1%}</td><td>{r["english_token_recall"]:.1%}</td><td>{r["devanagari_token_recall"]:.1%}</td><td>{r["mixed_wer"]:.1%}</td><td>{r["p50_latency_ms"]:.0f} ms</td><td>{r["samples"]}</td></tr>' for r in rows)
    doc=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hinglish STT benchmark · voice-router</title><style>@font-face{{font-family:g;src:url(https://cdn.jsdelivr.net/npm/geist@1.3.1/dist/fonts/geist-sans/Geist-Variable.woff2)}}@font-face{{font-family:m;src:url(https://cdn.jsdelivr.net/npm/geist@1.3.1/dist/fonts/geist-mono/GeistMono-Variable.woff2)}}*{{box-sizing:border-box}}body{{margin:0;font-family:g;color:#111}}a{{color:inherit}}nav{{border-bottom:1px solid #e8e8e8;height:57px;display:flex;align-items:center}}.w{{width:100%;max-width:1152px;margin:auto;padding:0 24px}}nav .w{{display:flex;justify-content:space-between}}nav a{{text-decoration:none;margin-left:18px;font-size:13px;color:#666}}nav b{{font-size:15px}}main{{padding-top:64px;padding-bottom:80px}}.ey{{font:11px m;letter-spacing:.14em;text-transform:uppercase;color:#777}}h1{{font-size:38px;letter-spacing:-.04em;font-weight:520;margin:14px 0}}.lead{{font-size:16px;color:#666;line-height:1.65;max-width:740px}}.meta{{margin-top:30px;font:12px m;color:#777}}section{{margin-top:62px}}h2{{font-size:21px;font-weight:520}}.sub{{font-size:13px;color:#777;line-height:1.6;max-width:740px}}.card{{border:1px solid #e5e5e5;border-radius:12px;overflow:auto;margin-top:20px}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{padding:14px 15px;border-bottom:1px solid #eee;text-align:right;white-space:nowrap}}th{{font:10px m;letter-spacing:.1em;color:#777;text-transform:uppercase}}th:first-child,th:nth-child(2),td:first-child,td:nth-child(2){{text-align:left}}td:first-child{{font-weight:600}}td{{font-family:m}}tr:last-child td{{border:0}}.note{{padding:22px;background:#f7f7f8;border-radius:12px;color:#555;line-height:1.7;font-size:13px;margin-top:20px}}@media(max-width:700px){{h1{{font-size:31px}}nav span{{display:none}}}}</style></head><body><nav><div class="w"><b>● voice-router</b><span><a href="../">Leaderboard</a><a href="../turn-taking/">Turn-taking</a><a href="../arena/">Arena</a></span></div></nav><main class="w"><p class="ey">Code-switching · STT</p><h1>Hinglish breaks monolingual rankings.</h1><p class="lead">The same 12 real Hindi-English utterances through every provider. We score whether both scripts survive, not whether one language gets flattened into the other.</p><p class="meta">RUN {e(p['generated_at'][:10])} · 12 SPEAKERS · 85.8 SECONDS · CC-BY-4.0</p><section><p class="ey">Measured results</p><h2>Balanced retention is the primary rank</h2><p class="sub">Script balance averages English-token and Devanagari-token recall. Mixed WER uses the exact mixed-script reference. Lower WER and latency are better; all recalls are higher-is-better.</p><div class="card"><table><thead><tr><th>Provider</th><th>Model</th><th>Script balance</th><th>English recall</th><th>Devanagari recall</th><th>Mixed WER</th><th>p50 latency</th><th>n</th></tr></thead><tbody>{trs}</tbody></table></div></section><section><p class="ey">Corpus receipt</p><h2>Real speech, mixed inside each utterance</h2><div class="note">Twelve distinct-speaker clips from the MUCS-Hinglish test split. Every reference contains at least three English and three Devanagari tokens; English share is 21%-50%. The exact selection rule, source shard, segment IDs, references, audio, provider hypotheses, and per-run scores are public in the <a href="data/results.json">raw JSON</a> and <a href="https://github.com/DeepanshuPal/voice-router/tree/main/benchmarks/code_switching">repository</a>. A Hindi language hint is sent consistently to all providers.</div></section></main></body></html>'''
    OUT.mkdir(parents=True,exist_ok=True); (OUT/'index.html').write_text(doc); (OUT/'data').mkdir(exist_ok=True); (OUT/'data/results.json').write_text(json.dumps(p,indent=2,ensure_ascii=False)+'\n'); print('wrote',OUT)
if __name__=='__main__': main()
